import{_ as a,C as n,o as l,c as p,H as e,Q as o}from"./chunks/framework.be8d362c.js";const m=JSON.parse('{"title":"解锁小米路由器ssh并安装v2ray及openwrt系统","description":"解锁小米路由器 ssh 功能，再原固件系统上安装 v2ray 客户端配置代理实现无qiang模式的科学上网，并同时在此基础上尝试再安装 openwrt 固件配置实现双系统共存模式；","frontmatter":{"date":"2024-01-10T00:00:00.000Z","title":"解锁小米路由器ssh并安装v2ray及openwrt系统","tags":["路由器","科学上网","v2ray","openwrt"],"description":"解锁小米路由器 ssh 功能，再原固件系统上安装 v2ray 客户端配置代理实现无qiang模式的科学上网，并同时在此基础上尝试再安装 openwrt 固件配置实现双系统共存模式；"},"headers":[],"relativePath":"posts/unlock-router-ssh-and-install-openwrt-v2ray.md","filePath":"posts/unlock-router-ssh-and-install-openwrt-v2ray.md"}'),t={name:"posts/unlock-router-ssh-and-install-openwrt-v2ray.md"},r=o(`<h1 id="解锁小米路由器ssh并安装v2ray及openwrt系统" tabindex="-1">解锁小米路由器ssh并安装v2ray及openwrt系统 <a class="header-anchor" href="#解锁小米路由器ssh并安装v2ray及openwrt系统" aria-label="Permalink to &quot;解锁小米路由器ssh并安装v2ray及openwrt系统&quot;">​</a></h1><p>通过 Google 引擎搜索看了一下网上分享破解小米路由器 ssh 功能的文章中都提及一条件：需要一台已运行的 openwrt 的路由器用于运行脚本，但个人当时第一反应是：这个感觉有点类似于陷入先有鸡才有蛋，还是先有蛋才有鸡的问题， 因为要有 openwrt 路由器通常就应该就要先破解 ssh 功能，那是先有 openwrt 再才能破解 ssh 功能，还是先破解了 ssh 功能再刷有 openwrt 路由器呢？<br> 于是，就简单剖析看了一下需要 openwrt 路由器的这一条件实际是做什么处理动作功能的，是否有可替代的方式来实现呢；<br> 其实这里需要的 openwrt 路由器提供的作用大概就两点：</p><ul><li>相当于 AP 功能提供 wifi 热点用于给要破解的 小米 路由器连接；</li><li>部署运行一个脚本，该脚本提供的功能其实只是实现提供一个webserver https 服务，供访问某特定 url 用于向该 AP 其连接下（即这里要破解的小米路由器）注入启动 ssh 功能的服务（即小米路由器自身 openwrt 系统基于 dropbear 服务来实现 ssh 功能的）； 了解后，按理其实只需要能够拥有 AP 功能提供 wifi 热点及部署提供 webserver 服务的设备系统即可，并非要求一定得是 openwrt 路由器，比如普通带有支持开热点的无线网卡的系统设备（树莓派、linux系统等）；<br> 理清思路后，这里个人这里选择借助闲置的树莓派开搞</li></ul><h2 id="首先需要解锁一下-ssh-功能" tabindex="-1">首先需要解锁一下 ssh 功能 <a class="header-anchor" href="#首先需要解锁一下-ssh-功能" aria-label="Permalink to &quot;首先需要解锁一下 ssh 功能&quot;">​</a></h2><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h3><ul><li>准备将树莓派烧制进 ubuntu 22.04 系统；<br> 这个可以参考 <a href="https://log.yousri.org/posts/across-to-the-world-without-gfw.html#raspberry-pi-%E5%88%9D%E5%A7%8B%E5%8C%96%E7%B3%BB%E7%BB%9F%E9%85%8D%E7%BD%AE" target="_blank" rel="noreferrer">Raspberry Pi 初始化系统配置</a></li><li>配置开启 AP 功能提供 wifi 热点； 参考网上作者分享的在openwrt上运行的<a href="https://github.com/shell-script/unlock-redmi-ax3000" target="_blank" rel="noreferrer">脚本</a>，解锁所需的操作可被简化为设置一个静态IP，网关为169.254.31.1的 wifi 热点，同时在网关上部署 webserver 提供能接收 POST 的 api 接口，接口路径为 <code>/cgi-bin/luci/api/xqsystem/token</code> ；</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>这一步只需要提供开启 AP 热点功能 和 配置静态 IP 即可；配置静态 IP 与 Linux 的发行版有关，因为这里选择树莓派使用的是netplan。具体步骤可请参考不同 Linux 使用的网络配置方式；</p></div><h3 id="使用-hostapd-配置提供-ap-热点功能" tabindex="-1">使用 hostapd 配置提供 AP 热点功能 <a class="header-anchor" href="#使用-hostapd-配置提供-ap-热点功能" aria-label="Permalink to &quot;使用 hostapd 配置提供 AP 热点功能&quot;">​</a></h3><ul><li>安装 hostapd：</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">apt</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">install</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">hostapd</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">sudo</span><span style="color:#24292E;"> </span><span style="color:#032F62;">apt</span><span style="color:#24292E;"> </span><span style="color:#032F62;">install</span><span style="color:#24292E;"> </span><span style="color:#032F62;">hostapd</span></span></code></pre></div><ul><li>创建 hostapd 热点配置文件 <code>/etc/hostapd/hostapd.conf</code> (这里使用的 SSID 为 xiaomi，密码为xiaomi123456)</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#9ECBFF;">interface=wlan0</span></span>
<span class="line"><span style="color:#9ECBFF;">driver=nl80211</span></span>
<span class="line"><span style="color:#9ECBFF;">ssid=xiaomi</span></span>
<span class="line"><span style="color:#9ECBFF;">hw_mode=g</span></span>
<span class="line"><span style="color:#9ECBFF;">channel=7</span></span>
<span class="line"><span style="color:#9ECBFF;">wmm_enabled=0</span></span>
<span class="line"><span style="color:#9ECBFF;">macaddr_acl=0</span></span>
<span class="line"><span style="color:#9ECBFF;">auth_algs=1</span></span>
<span class="line"><span style="color:#9ECBFF;">ignore_broadcast_ssid=0</span></span>
<span class="line"><span style="color:#9ECBFF;">wpa=2</span></span>
<span class="line"><span style="color:#9ECBFF;">wpa_passphrase=xiaomi123456</span></span>
<span class="line"><span style="color:#9ECBFF;">wpa_key_mgmt=WPA-PSK</span></span>
<span class="line"><span style="color:#9ECBFF;">wpa_pairwise=TKIP</span></span>
<span class="line"><span style="color:#9ECBFF;">rsn_pairwise=CCMP</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#032F62;">interface=wlan0</span></span>
<span class="line"><span style="color:#032F62;">driver=nl80211</span></span>
<span class="line"><span style="color:#032F62;">ssid=xiaomi</span></span>
<span class="line"><span style="color:#032F62;">hw_mode=g</span></span>
<span class="line"><span style="color:#032F62;">channel=7</span></span>
<span class="line"><span style="color:#032F62;">wmm_enabled=0</span></span>
<span class="line"><span style="color:#032F62;">macaddr_acl=0</span></span>
<span class="line"><span style="color:#032F62;">auth_algs=1</span></span>
<span class="line"><span style="color:#032F62;">ignore_broadcast_ssid=0</span></span>
<span class="line"><span style="color:#032F62;">wpa=2</span></span>
<span class="line"><span style="color:#032F62;">wpa_passphrase=xiaomi123456</span></span>
<span class="line"><span style="color:#032F62;">wpa_key_mgmt=WPA-PSK</span></span>
<span class="line"><span style="color:#032F62;">wpa_pairwise=TKIP</span></span>
<span class="line"><span style="color:#032F62;">rsn_pairwise=CCMP</span></span></code></pre></div><ul><li>修改 /etc/default/hostapd，在里面添加一行：</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#9ECBFF;">DAEMON_CONF=&quot;/etc/hostapd/hostapd.conf&quot;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#032F62;">DAEMON_CONF=&quot;/etc/hostapd/hostapd.conf&quot;</span></span></code></pre></div><ul><li>启动 hostapd 服务</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">systemctl</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">start</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">hostapd</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">sudo</span><span style="color:#24292E;"> </span><span style="color:#032F62;">systemctl</span><span style="color:#24292E;"> </span><span style="color:#032F62;">start</span><span style="color:#24292E;"> </span><span style="color:#032F62;">hostapd</span></span></code></pre></div>`,16);function c(i,d,h,y,u,F){const s=n("Comment");return l(),p("div",null,[r,e(s)])}const _=a(t,[["render",c]]);export{m as __pageData,_ as default};
